import java.lang.invoke.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;

/** Generated by jdec recover. Runs the target jar's own indy bootstrap
 *  machinery per site, with keys evaluated from THIS run's field values
 *  (self-consistent replay). Never run untrusted jars with elevated
 *  permissions: this executes target-code decryption paths. */
public class RecoverDriver {
    static Map<String, Long> fields = new HashMap<>();
    static Map<String, Method> bsmCache = new HashMap<>();
    static Map<String, Object[]> bsmStatics = new HashMap<>();
    static Map<Class<?>, Method[]> refCache = new HashMap<>();
    static ClassLoader cl;

    /** 在引导类里找引用解密器：(long,long)->Field 与 (long,long)->Method 的
     *  静态方法（ZKM 系惯例）。找不到返回 [null,null]，调用方如实报告。 */
    static String decodeRef(Class<?> c, long l, long l2) throws Exception {
        Method[] dm = refCache.get(c);
        if (dm == null) {
            Method f = null, m = null;
            for (Method x : c.getMethods()) {
                Class<?>[] pt = x.getParameterTypes();
                if (pt.length == 2 && pt[0] == long.class && pt[1] == long.class) {
                    if (x.getReturnType() == Field.class && f == null) f = x;
                    if (x.getReturnType() == Method.class && m == null) m = x;
                }
            }
            dm = new Method[]{f, m};
            refCache.put(c, dm);
        }
        if (dm[0] != null) {
            Field fl = (Field) dm[0].invoke(null, l, l2);
            return "field " + fl.getDeclaringClass().getName()
                    + "." + fl.getName() + " : " + fl.getType().getName();
        }
        if (dm[1] != null) {
            Method me = (Method) dm[1].invoke(null, l, l2);
            StringBuilder sb = new StringBuilder("method ")
                    .append(me.getDeclaringClass().getName())
                    .append(".").append(me.getName()).append('(');
            Class<?>[] pt = me.getParameterTypes();
            for (int i = 0; i < pt.length; i++) {
                if (i > 0) sb.append(',');
                sb.append(pt[i].getName());
            }
            return sb.append(") : ").append(me.getReturnType().getName()).toString();
        }
        return "no-ref-decoder";
    }

    public static void main(String[] args) throws Exception {
        List<String> lines = Files.readAllLines(Paths.get(args[0]));
        cl = RecoverDriver.class.getClassLoader();
        String fqcn = null;
        Method[] bsms = new Method[64];
        int ok = 0, fail = 0, skip = 0, ref = 0;
        for (String line : lines) {
            if (line.isBlank()) continue;
            try {
                if (line.startsWith("C\t")) {
                    fqcn = line.substring(2);
                    fields.clear();
                    bsms = new Method[64];
                    // bsmStatics 按 B 行条目 idx 键存（idx 类内有效），换类必须清——
                    // 否则上个类的残留会喂给本类同 idx 的站点
                    bsmStatics.clear();
                    Class<?> c = Class.forName(fqcn, true, cl);
                    for (Field f : c.getDeclaredFields())
                        if (f.getType() == long.class
                                && Modifier.isStatic(f.getModifiers())) {
                            f.setAccessible(true);
                            fields.put(fqcn + "." + f.getName(), f.getLong(null));
                        }
                } else if (line.startsWith("B\t")) {
                    String[] p = line.split("\t", -1);
                    int idx = Integer.parseInt(p[1]);
                    if (idx >= bsms.length)
                        bsms = Arrays.copyOf(bsms, idx + 1);
                    Method m = resolveBsm(p[2], p[3], p[4]);
                    if (m == null)
                        throw new RuntimeException("bsm not found: " + p[2] + "." + p[3]);
                    bsms[idx] = m;
                    MethodType bmt = MethodType.fromMethodDescriptorString(p[4], cl);
                    Class<?>[] bpt = bmt.parameterArray();
                    int nstatic = bpt.length - 3;   // 前三个固定是 Lookup/String/MT
                    Object[] stat = new Object[Math.max(0, nstatic)];
                    for (int i = 0; i < nstatic; i++)
                        stat[i] = decodeStatic(p[5 + i], bpt[3 + i]);
                    // 静态参数按条目 idx 存取（不是按方法签名！）：同一解密器
                    // 方法会被同类的多个条目共用，而每个条目携带各自的
                    // (cipher, seed)——按签名做键会互相覆盖，全部站点都拿到
                    // 最后一个条目的参数（JadeOffline 实测坑掉 2730/6516 站点）。
                    bsmStatics.put("B" + idx, stat);
                } else if (line.startsWith("S\t")) {
                    String[] p = line.split("\t", -1);
                    int bsmIdx = Integer.parseInt(p[1]);
                    String siteName = p[2];
                    String siteDesc = p[3];
                    int na = Integer.parseInt(p[4]);
                    String kind = p[5];            // REF = 成员引用隐藏 / STR = 字符串解密
                    Method bsm = bsmIdx < bsms.length ? bsms[bsmIdx] : null;
                    if (bsm == null) {
                        System.out.println("SKIP\t" + fqcn + "\t" + siteName + "\tno-bsm");
                        skip++; continue;
                    }
                    Object[] dyn = new Object[na];
                    boolean bad = false;
                    for (int i = 0; i < na; i++) {
                        Object v = eval(p[6 + i]);
                        if (v == null) { bad = true; break; }
                        dyn[i] = (v == NULL) ? null : box((Long) v, argKind(siteDesc, i));
                    }
                    if (bad) {
                        System.out.println("SKIP\t" + fqcn + "\t" + siteName + "\tunevaluable");
                        skip++; continue;
                    }
                    if (kind.equals("REF")) {
                        // 成员引用站点：尾部两个 long 是加密引用。**不执行目标方法**
                        //（setter/void 有副作用），只调目标类自带的引用解密器
                        //（(long,long)->Field/Method 的静态方法）拿 owner.name。
                        Object l = dyn[na - 2], l2 = dyn[na - 1];
                        if (!(l instanceof Long) || !(l2 instanceof Long)) {
                            System.out.println("SKIP\t" + fqcn + "\t" + siteName + "\tref-tail-not-long");
                            skip++; continue;
                        }
                        String info = decodeRef(bsm.getDeclaringClass(),
                                (Long) l, (Long) l2);
                        System.out.println("REF\t" + fqcn + "\t" + siteName + "\t" + esc(info));
                        ref++;
                        continue;
                    }
                    // 静态参数（BootstrapMethods 属性里的）传给 bootstrap；
                    // 动态参数属于 bootstrap 安装的 target，不能混进来
                    Object[] stat = bsmStatics.getOrDefault("B" + bsmIdx, new Object[0]);
                    List<Object> call = new ArrayList<>();
                    call.add(lookupFor(bsm.getDeclaringClass()));
                    call.add(siteName);
                    call.add(MethodType.fromMethodDescriptorString(siteDesc, cl));
                    call.addAll(Arrays.asList(stat));
                    Object result = bsm.invoke(null, call.toArray());
                    Object unwrapped = (result instanceof CallSite)
                            ? ((CallSite) result).getTarget() : result;
                    Object out;
                    if (unwrapped instanceof MethodHandle mh) {
                        // 右对齐：目标句柄 arity 与提取到的参数数可能不一致，
                        // 缺的前端用 null 补（对象占位参数），多的截掉
                        int pc = mh.type().parameterCount();
                        Object[] pass = new Object[pc];
                        for (int i = 0; i < pc; i++) {
                            int di = dyn.length - pc + i;
                            pass[i] = di >= 0 ? dyn[di] : null;
                        }
                        out = mh.invokeWithArguments(pass);
                    } else
                        out = unwrapped;
                    // OK 行携带本条目的 (cipher, seed)：回填源码时的匹配键。
                    // 第一个 String 型静态参数视为 cipher，第一个数值型视为 seed。
                    String cipher = "-", seed = "-";
                    for (Object st : stat) {
                        if (cipher.equals("-") && st instanceof String s) cipher = s;
                        else if (seed.equals("-") && st instanceof Number n) seed = n.toString();
                    }
                    System.out.println("OK\t" + fqcn + "\t" + siteName + "\t"
                            + esc(cipher) + "\t" + seed + "\t" + esc(String.valueOf(out)));
                    ok++;
                }
            } catch (Throwable t) {
                Throwable r = t; while (r.getCause() != null) r = r.getCause();
                String tag = line.split("\t", 3)[1];
                System.out.println("FAIL\t" + (fqcn == null ? "?" : fqcn) + "\t" + tag
                        + "\t" + esc(String.valueOf(r)));
                if (t instanceof WrongMethodTypeException && fail < 999999)
                    t.printStackTrace(System.err);
                fail++;
            }
        }
        System.err.println("driver: ok=" + ok + " ref=" + ref
                + " fail=" + fail + " skip=" + skip);
    }

    static Method resolveBsm(String owner, String name, String bsmDesc) throws Exception {
        String key = owner + "." + name + ":" + bsmDesc;
        if (bsmCache.containsKey(key)) return bsmCache.get(key);
        Class<?> c = Class.forName(owner, true, cl);
        Method m = c.getDeclaredMethod(name, paramTypes(bsmDesc));
        m.setAccessible(true);
        bsmCache.put(key, m);
        return m;
    }

    static MethodHandles.Lookup lookupFor(Class<?> c) throws Exception {
        return MethodHandles.privateLookupIn(c, MethodHandles.lookup());
    }

    static Class<?>[] paramTypes(String bsmDesc) {
        return MethodType.fromMethodDescriptorString(bsmDesc, cl).parameterArray();
    }

    static Object decodeStatic(String enc, Class<?> kind) throws Exception {
        if (enc.startsWith("i:")) return Integer.parseInt(enc.substring(2));
        if (enc.startsWith("l:")) return Long.parseLong(enc.substring(2));
        if (enc.startsWith("s:")) return unesc(enc.substring(2));
        if (enc.startsWith("c:")) return Class.forName(enc.substring(2));
        if (enc.startsWith("mt:")) return MethodType.fromMethodDescriptorString(
                unesc(enc.substring(3)), cl);
        if (enc.equals("null")) return null;
        if (enc.startsWith("mh:")) {
            String[] parts = enc.substring(3).split(":", 4);
            int mkind = Integer.parseInt(parts[0]);
            Class<?> oc = Class.forName(parts[1].replace("/", "."));
            MethodHandles.Lookup lk = lookupFor(oc);
            MethodType mt2 = MethodType.fromMethodDescriptorString(
                    unesc(parts[3]), cl);
            if (mkind == 6) return lk.findStatic(oc, parts[2], mt2);
            if (mkind == 5 || mkind == 7) return lk.findVirtual(oc, parts[2], mt2);
            return null;
        }
        Object v = unboxLoose(enc);
        if (kind == int.class) return (int) ((Long) v).longValue();
        if (kind == long.class) return (Long) v;
        if (kind == boolean.class) return v == Long.valueOf(1);
        return v;
    }

    static Object unboxLoose(String enc) {
        if (enc.startsWith("i:") || enc.startsWith("l:"))
            return Long.parseLong(enc.substring(2));
        return null;
    }

    static String argKind(String siteDesc, int i) {
        String params = siteDesc.substring(1, siteDesc.indexOf(')'));
        int n = -1, i2 = 0;
        while (i2 < params.length()) {
            n++;
            char ch = params.charAt(i2);
            if (ch == 'D' || ch == 'J') i2 += 2;
            else if (ch == 'L') i2 = params.indexOf(';', i2) + 1;
            else if (ch == '[') {
                while (params.charAt(i2) == '[') i2++;
                if (params.charAt(i2) == 'L') i2 = params.indexOf(';', i2) + 1; else i2++;
            } else i2++;
            if (n == i) return String.valueOf(ch);
        }
        return "?";
    }

    static Object box(long v, String kind) {
        switch (kind) {
            case "I": case "S": case "B": case "C": case "Z": return (int) v;
            default: return v;
        }
    }

    static final Object NULL = new Object();

    static Object eval(String stack) {
        if (stack == null || stack.isEmpty() || stack.equals("?")) return null;
        Deque<Object> st = new ArrayDeque<>();
        for (String t : stack.split(" ")) {
            if (t.isEmpty()) continue;
            if (t.equals("null")) { st.push(NULL); continue; }
            if (t.startsWith("lit:")) st.push(Long.parseLong(t.substring(4)));
            else if (t.startsWith("fld:")) {
                String ref = t.substring(4).replace("/", ".");
                Long v = fields.get(ref);
                if (v == null) {
                    int dot = ref.lastIndexOf('.');
                    try {
                        Class<?> oc = Class.forName(ref.substring(0, dot), true, cl);
                        Field f = oc.getDeclaredField(ref.substring(dot + 1));
                        f.setAccessible(true);
                        v = f.getLong(null);
                        fields.put(ref, v);
                    } catch (Throwable e) { return null; }
                }
                st.push(v);
            } else {
                Object b = st.poll(), a = st.poll();
                if (a == null || b == null || a == NULL || b == NULL) return null;
                long A = (Long) a, B = (Long) b;
                switch (t) {
                    case "lxor": case "ixor": st.push(A ^ B); break;
                    case "lor": case "ior": st.push(A | B); break;
                    case "land": case "iand": st.push(A & B); break;
                    case "ladd": case "iadd": st.push(A + B); break;
                    case "lsub": case "isub": st.push(A - B); break;
                    case "lmul": case "imul": st.push(A * B); break;
                    case "lshl": case "ishl": st.push(A << B); break;
                    case "lshr": case "ishr": st.push(A >> B); break;
                    case "lushr": case "iushr": st.push(A >>> B); break;
                    case "l2i": st.push((long) (int) A); break;
                    case "i2l": st.push(A); break;
                    case "lneg": case "ineg": st.push(-A); break;
                    default: return null;
                }
            }
        }
        return st.size() == 1 ? st.poll() : null;
    }

    static String unesc(String s) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\' && i + 1 < s.length()) {
                char n = s.charAt(++i);
                out.append(switch (n) {
                    case 't' -> '\t'; case 'n' -> '\n'; case 'r' -> '\r';
                    default -> n;
                });
            } else out.append(c);
        }
        return out.toString();
    }

    static String esc(String s) {
        return s.replace("\\", "\\\\").replace("\t", "\\t")
                .replace("\n", "\\n").replace("\r", "\\r");
    }
}
